using System.ComponentModel;
using Microsoft.Extensions.AI;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Logging;
using Microsoft.Agents.AI;
using Microsoft.Agents.AI.ChatCompletion;

var services = new ServiceCollection();

services.AddLogging(builder => builder
    .AddConsole()
    .SetMinimumLevel(LogLevel.Information));

var apiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY")
    ?? throw new InvalidOperationException(
        "Set the OPENAI_API_KEY environment variable to run this agent.");

services.AddChatClient(builder => builder
    .UseOpenAIChatClient("gpt-4o-mini-2024-07-18", apiKey));

var sp = services.BuildServiceProvider();
var chatClient = sp.GetRequiredService<IChatClient>();
var logger = sp.GetRequiredService<ILogger<Program>>();

// Define the tools available to the agent
var tools = new ResearchTools();
var chatOptions = new ChatOptions
{
    Temperature = 0f,
    MaxOutputTokens = 2048,
    Tools = [
        AIFunctionFactory.Create(tools.SearchWeb),
        AIFunctionFactory.Create(tools.TakeNote),
        AIFunctionFactory.Create(tools.GetNotes),
    ],
};

// Create the agent using Microsoft Agent Framework
var agent = new ChatClientAgent(chatClient, "ResearchAgent")
{
    Instructions = """
        You are a research agent. Given a topic, you:
        1. Search the web for relevant information using the SearchWeb tool.
        2. Take notes on key findings using the TakeNote tool.
        3. After gathering enough information (at least 2-3 searches), retrieve your notes
           with GetNotes and produce a concise summary of your research.
        Always cite the sources you found.
        """,
};

// Get the research topic from the user
Console.Write("Enter a research topic: ");
var topic = Console.ReadLine()?.Trim();
if (string.IsNullOrEmpty(topic))
{
    Console.WriteLine("No topic provided. Exiting.");
    return;
}

Console.WriteLine($"\nResearching: {topic}\n");

// Run the agent with iteration limits
var history = new List<ChatMessage>
{
    new(ChatRole.User, $"Research the following topic and provide a summary: {topic}"),
};

var invokeOptions = new AgentInvokeOptions
{
    MaximumIterations = 10,
    ChatOptions = chatOptions,
};

await foreach (var message in agent.InvokeStreamingAsync(history, invokeOptions))
{
    if (message.Role == ChatRole.Assistant && !string.IsNullOrEmpty(message.Text))
    {
        Console.Write(message.Text);
    }
}

Console.WriteLine();

/// <summary>
/// Tools available to the research agent for web searching and note-taking.
/// </summary>
sealed class ResearchTools
{
    private readonly List<string> _notes = [];

    [Description("Searches the web for information on a given query. Returns a list of relevant results with titles, snippets, and URLs.")]
    public string SearchWeb(
        [Description("The search query to look up on the web")] string query)
    {
        // Simulated web search results for demonstration purposes.
        // In production, replace with a real search API (e.g., Bing Search, Google Custom Search).
        var results = $"""
            Search results for: "{query}"

            1. Title: "{query}" - Wikipedia Overview
               URL: https://en.wikipedia.org/wiki/{Uri.EscapeDataString(query)}
               Snippet: A comprehensive overview of {query}, covering history, key concepts, and recent developments.

            2. Title: Latest Research on {query} - Science Daily
               URL: https://www.sciencedaily.com/search/?keyword={Uri.EscapeDataString(query)}
               Snippet: Recent studies and breakthroughs related to {query}, including findings from leading research institutions.

            3. Title: {query}: A Practical Guide - TechReview
               URL: https://www.techreview.com/topic/{Uri.EscapeDataString(query)}
               Snippet: An in-depth practical guide explaining {query}, its applications, challenges, and future outlook.
            """;

        return results;
    }

    [Description("Saves a research note. Use this to record important findings during research.")]
    public string TakeNote(
        [Description("The note content to save")] string note,
        [Description("The source URL or reference for this note")] string source)
    {
        _notes.Add($"[Source: {source}] {note}");
        return $"Note saved. You now have {_notes.Count} note(s).";
    }

    [Description("Retrieves all saved research notes.")]
    public string GetNotes()
    {
        if (_notes.Count == 0)
        {
            return "No notes have been taken yet.";
        }

        return "Collected Research Notes:\n" + string.Join("\n\n", _notes.Select((n, i) => $"{i + 1}. {n}"));
    }
}

